:root{
  --bg:#f6f4ee; --surface:#ffffff; --ink:#1c2430; --muted:#5b6673;
  --line:#ddd8cc; --accent:#0b5cad; --accent-soft:#e3eefb; --row:#faf9f5;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);
  font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
h1{font-size:28px;margin:0 0 4px}
h2{font-size:19px;margin:0 0 8px}
h3{font-size:16px;margin:18px 0 6px}
.head{display:flex;gap:24px;justify-content:space-between;align-items:flex-start;
  padding:20px 24px 14px;border-bottom:1px solid var(--line)}
.sub{margin:0;color:var(--muted);max-width:760px}
.head-note{max-width:340px;font-size:13px;color:var(--muted);
  background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:10px 12px}
.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:14px 24px}
.controls input[type=search]{flex:1 1 220px;min-width:180px}
.controls input,.controls select,.controls button{
  font:inherit;color:var(--ink);background:var(--surface);
  border:1px solid var(--line);border-radius:6px;padding:7px 10px}
.controls button{cursor:pointer}
.controls button.on{background:var(--accent);border-color:var(--accent);color:#fff}
.chk{display:flex;gap:6px;align-items:center;white-space:nowrap}
.views{margin-left:auto;display:flex;gap:6px}
.count{margin:0 24px 8px;color:var(--muted);font-size:13px}
main{padding:0 24px 24px}
table{width:100%;border-collapse:collapse;background:var(--surface);
  border:1px solid var(--line);border-radius:8px;overflow:hidden}
th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}
thead th{background:var(--row);font-size:12px;text-transform:uppercase;
  letter-spacing:.04em;color:var(--muted);position:sticky;top:0}
tbody tr:nth-child(even){background:var(--row)}
tbody tr{cursor:pointer}
tbody tr:hover{background:var(--accent-soft)}
tbody tr.sel{background:var(--accent-soft)}
.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.rank{color:var(--accent);font-weight:700;white-space:nowrap}
.range{display:block;font-size:11px;color:var(--muted);font-weight:400}
.slug{display:block;font-size:12px;color:var(--muted)}
.badge{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.03em;
  background:var(--accent);color:#fff;border-radius:4px;padding:1px 6px;margin-left:6px}
.tag{display:inline-block;font-size:11px;font-weight:700;color:var(--accent);
  border:1px solid var(--accent);border-radius:4px;padding:0 5px;margin-left:6px}
.detail{background:var(--surface);border:1px solid var(--accent);border-radius:10px;
  padding:18px 20px;margin:18px 0}
.detail h2{font-size:21px}
.detail .meta{color:var(--muted);margin:0 0 12px}
.detail h3{margin-top:20px}
.detail table{margin:8px 0}
.detail tbody tr{cursor:default}
.detail tbody tr:hover{background:inherit}
.median-row{background:var(--accent-soft)!important;font-weight:600}
.drivers{margin:6px 0 0;padding-left:20px}
.drivers li{margin:3px 0}
.steps{margin:6px 0 0;padding-left:22px}
.steps li{margin:7px 0}
.totals{margin:12px 0 0;padding:10px 12px;background:var(--accent-soft);
  border-radius:6px;font-weight:600}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:10px;
  padding:18px 20px;margin:18px 0}
.formula{font-weight:700;background:var(--row);border:1px solid var(--line);
  border-radius:6px;padding:10px 12px}
.formula-list{margin:10px 0 0;padding-left:20px}
.formula-list li{margin:5px 0}
.note{color:var(--muted);font-size:13px}
footer{padding:0 24px 24px;color:var(--muted);font-size:13px}
@media (max-width:900px){
  .head{flex-direction:column}
  .head-note{max-width:none}
  th:nth-child(3),td:nth-child(3),th:nth-child(7),td:nth-child(7){display:none}
}
